function ball(g,T,x,y,z,r,c,name='',scale=[1,1,1]){let m=new T.Mesh(new T.SphereGeometry(r,28,20),new T.MeshStandardMaterial({color:c,roughness:.32,metalness:.04}));m.position.set(x,y,z);m.scale.set(...scale);m.name=name;g.add(m);return m;}
function rod(g,T,a,b,r,c,name=''){let p=new T.Vector3(...a),q=new T.Vector3(...b),d=q.clone().sub(p),m=new T.Mesh(new T.CylinderGeometry(r,r,d.length(),20),new T.MeshStandardMaterial({color:c,roughness:.35}));m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());m.name=name;g.add(m);}
export function buildResp(g,T,w={}){let k=w.kind||'mitochondrion',s=w.state||'oxygen';
if(k==='mitochondrion'){let shell=new T.Mesh(new T.SphereGeometry(1.1,48,32,Math.PI,Math.PI),new T.MeshStandardMaterial({color:0xbb9e86,side:T.DoubleSide,roughness:.33}));shell.scale.set(1.7,.85,.8);shell.name='mitochondrion-cutaway';g.add(shell);let points=[];for(let i=0;i<7;i++){let x=-1.4+i*.43;for(let [dx,y]of[[0,-.45],[.04,.38],[.14,.38],[.18,-.45]])points.push(new T.Vector3(x+dx,y,.12));}let fold=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(points),240,.065,12,false),new T.MeshStandardMaterial({color:0xe3cba8,roughness:.3}));fold.name='inner-fold';g.add(fold);if(s!=='no-oxygen')for(let i=0;i<6;i++)ball(g,T,-1.1+i*.42,-.85,.3,.09,0xabc9cf,'oxygen-marker');return;}
if(k==='fermentation'){if(s==='muscle'){buildResp(g,T,{kind:'muscle',state:'sufficient'});return;}let jar=new T.Mesh(new T.CylinderGeometry(.9,.9,2.1,40,1,true),new T.MeshStandardMaterial({color:0xb4cdd0,transparent:true,opacity:.2,side:T.DoubleSide}));jar.name='fermentation-vessel';g.add(jar);for(let i=0;i<12;i++)ball(g,T,Math.sin(i*2.4)*.6,-.7+(i%4)*.3,Math.cos(i*2.4)*.4,.13,0xd2b38f,'yeast-cell',[1,.7,.7]);if(s!=='muscle')for(let i=0;i<6;i++)ball(g,T,-.45+i*.18,.6+i%3*.24,.3,.06,0xb1d0d3,'carbon-dioxide');return;}
if(k==='muscle'||k==='exercise'){for(let i=0;i<8;i++)rod(g,T,[-1.4,-.75+i*.2,Math.sin(i)*.15],[1.4,-.65+i*.2,Math.sin(i)*.15],.1,0xc29383,'muscle-fibre');for(let i=0;i<(s==='insufficient'?2:8);i++)ball(g,T,-1.3+i*.35,1,.25,.085,0xb6cfd1,'oxygen-delivery');return;}
if(k==='lipid'){let gs=Math.min(3,Math.max(0,Number(w.glycerol??1))),fs=Math.min(5,Math.max(0,Number(w.fatty??3)));for(let i=0;i<gs;i++){for(let j=0;j<3;j++)ball(g,T,-1.1+i*.3,.55-j*.4,0,.16,0xaac6cb,'glycerol-unit');}for(let i=0;i<fs;i++)for(let j=0;j<6;j++)ball(g,T,-.5+j*.35,.8-i*.4,.1,.12,0xd9b18e,'fatty-acid-unit');return;}
if(k==='yield'){for(let i=0;i<(s==='anaerobic'?2:8);i++)ball(g,T,-1.1+i%4*.7,-.5+Math.floor(i/4)*.9,0,.24,0xdcb88e,'energy-symbol');return;}
if(k==='recovery'){for(let i=0;i<4;i++){let b=ball(g,T,-1.5+i,0,0,.36,i===Math.min(3,w.step??0)?0xd6a68c:0x9eb9b5,'route-node');if(i<3)rod(g,T,[-1.13+i,0,0],[-.87+i,0,0],.035,0xdac9aa,'transport-link');}return;}
if(k==='metabolism'||k==='blocks'){if(s==='lipid'){buildResp(g,T,{kind:'lipid',glycerol:1,fatty:3});return;}if(s==='urea'){for(let i=0;i<8;i++)ball(g,T,-1.2+(i%2)*.25,-.65+Math.floor(i/2)*.4,0,.14,0xd1af98,'protein-input');rod(g,T,[-.5,0,0],[.5,0,0],.04,0xd8c5a7,'waste-route');for(let i=0;i<3;i++)ball(g,T,1,.45-i*.45,0,.16,0xb8cdd0,'urea-symbol');return;}let points=[];if(s==='cellulose'){for(let row=0;row<3;row++)for(let i=0;i<7;i++){ball(g,T,-1.35+i*.43,-.55+row*.55,0,.15,0xc9b18f,'cellulose-unit');if(i)rod(g,T,[-1.35+(i-1)*.43,-.55+row*.55,0],[-1.35+i*.43,-.55+row*.55,0],.04,0xe0c8a6);}return;}for(let i=0;i<12;i++){let a=i*.6,x=s==='glycogen'?-1.3+i*.23:Math.cos(a)*(s==='protein'?1.15:.9),y=s==='glycogen'?0:Math.sin(a)*.7,z=s==='protein'?Math.sin(a*2)*.25:0;points.push([x,y,z]);ball(g,T,x,y,z,.15,s==='protein'?(i%2?0xb3cac8:0xd2ad98):0xcdb18d,s==='protein'?'amino-acid-unit':'glucose-derived-unit');if(i)rod(g,T,points[i-1],points[i],.04,0xe0c9ac);if(s==='glycogen'&&i%3===1)for(let j=1;j<=3;j++){ball(g,T,x+j*.1,j*.3,0,.13,0xcdb18d,'branch-unit');rod(g,T,[x+(j-1)*.1,(j-1)*.3,0],[x+j*.1,j*.3,0],.035,0xe0c9ac);}}return;}for(let i=0;i<12;i++)ball(g,T,-1.2+(i%4)*.75,-.65+Math.floor(i/4)*.6,0,.18,i<4?0xb7c9c9:0xd6b38e,'metabolic-unit');}
